 $inputs=@(@{file=$q;sha256='c04de09df4879842e299db9822c76e0b6e13a70c345cb9803d74722e25f24b7d'},
 @{file=$k;sha256='99bd880e732fd2786c12a68113fe5f834b5cc0fe87b09b0aaf5734c90bf3f2e8'},
 @{file=$v;sha256='bd95f94c94ea0606c94b6d98548a672e78479bf6df2d7ace08f3797a85907e80'},
